<?php
declare(strict_types=1);
ob_start();require dirname(__DIR__).'/portal-private/bootstrap.php';
$path=getenv('PORTAL_CONFIG_FILE');if(!$path||!str_ends_with($path,'config.test.php'))throw new RuntimeException('Solo config.test.php.');$config=require $path;if(!str_ends_with($config['db_name'],'_test'))throw new RuntimeException('Solo base _test.');
portal_app();$app=new PortalApp([...$config,'smtp'=>['enabled'=>false]]);$db=$app->db();PortalSchema::apply($db);$app->login(['username'=>'admin','password'=>'PruebaIntranet-2026!']);$count=0;
function check(bool $v,string $m):void{global $count;if(!$v)throw new RuntimeException($m);$count++;echo "OK $m\n";}
function edit(callable $f):void{global $app;$b=$app->bootstrap();$d=$b['data'];$f($d);$app->save(['data'=>$d,'revision'=>$b['revision']]);}
function messages(string $module,mixed $id,?string $event=null):array{global $db;$q=$db->prepare('SELECT * FROM intranet_mail WHERE source_type=? AND source_id=?'.($event?' AND event=?':'').' ORDER BY recipient');$q->execute($event?[$module,(string)$id,$event]:[$module,(string)$id]);return $q->fetchAll();}
function total():int{global $db;return (int)$db->query('SELECT COUNT(*) FROM intranet_mail')->fetchColumn();}
edit(function(&$d){$d['config']['lr']['correo']='responsable@example.test';$d['config']['correoReclamos']='responsable@example.test';$d['config']['bolsa']['correo']='empleabilidad@example.test';});
$claim=$app->bootstrap()['data']['reclamos'][0];$c=$app->challenge(['purpose'=>'reclamos']);$input=['record'=>$claim,'idempotency_key'=>implode('-',array_map('bin2hex',[random_bytes(4),random_bytes(2),random_bytes(2),random_bytes(2),random_bytes(6)])),'proof'=>['challenge_id'=>$c['id'],'answer'=>$_SESSION['challenges'][$c['id']]['answer'],'accept'=>true,'declare'=>true]];
$receipt=$app->submit('reclamos',$input);$id=$receipt['record']['id'];$m=messages('reclamos',$id,'registro');check(count($m)===2,'Reclamo genera constancia y un aviso institucional sin duplicar correos coincidentes');check(count(array_unique(array_column($m,'recipient')))===2,'Destinatarios separados');check($app->submit('reclamos',$input)['status']===200&&count(messages('reclamos',$id))===2,'Reenvío idempotente del formulario no duplica avisos');
$before=total();edit(function(&$d)use($id){foreach($d['reclamos'] as &$r)if($r['id']===$id)$r['notas'][]=['texto'=>'NOTA INTERNA SOLO PERSONAL'];});check(total()===$before,'Nota interna no genera correo');
edit(function(&$d){foreach($d['academico']['areas'] as &$a)if($a['cod']==='DG')$a['correo']='direccion@example.test';});
edit(function(&$d)use($id){foreach($d['reclamos'] as &$r)if($r['id']===$id){$r['area']='DG';$r['estado']='Derivado';}});check(count(messages('reclamos',$id,'seguimiento'))===2,'Derivación notifica al reclamante y al área');
edit(function(&$d)use($id){foreach($d['reclamos'] as &$r)if($r['id']===$id){$r['respuesta']='Respuesta formal para la persona reclamante.';$r['estado']='Atendido';}});$m=messages('reclamos',$id,'seguimiento');check(count($m)===3,'Respuesta institucional agrega un aviso al reclamante');check(count(array_filter($m,fn($r)=>str_contains($r['body'],'Respuesta formal')))==1,'Respuesta formal se envía solamente al destinatario personal');
foreach(messages('reclamos',$id) as $mail)check(!str_contains($mail['body'],'NOTA INTERNA'),'No se filtran notas internas');
$before=total();edit(fn(&$d)=>null);check(total()===$before,'Guardar sin cambios no genera notificaciones');
$data=$app->bootstrap()['data'];$company=$data['academico']['empresas'][0];$cid=$company['id'];check(count(messages('empresas',$cid,'registro'))>=1,'Registro de empresa genera confirmación');check(count(messages('empresas',$cid,'validacion'))>=1,'Aprobación institucional genera aviso');
edit(function(&$d)use($cid){foreach($d['academico']['empresas'] as &$r)if($r['id']===$cid){$r['validada']=false;$r['estadoVal']='Rechazada';$r['motivoRech']='Documentación pendiente de revisión.';}});check(count(messages('empresas',$cid,'validacion'))>=2,'Suspensión o rechazo se notifica');
$before=total();try{edit(function(&$d){$d['academico']['ofertas'][0]['vac']=0;});throw new RuntimeException('Validación omitida');}catch(PortalError $e){check($e->status===422&&total()===$before,'Cambio inválido no encola correos');}
$post=$data['academico']['postulaciones'][0];check(count(messages('postulaciones',$post['id'],'registro'))>=2,'Postulación confirma al estudiante y avisa a la empresa');
edit(function(&$d){foreach($d['academico']['postulaciones'] as &$r)if($r['id']===9001)$r['estado']='No seleccionado';});check(count(messages('postulaciones',9001,'estado'))>=2,'Cambio de postulación avisa a sus participantes');
$closedBefore=count(messages('ofertas',9001,'estado'));edit(function(&$d){foreach($d['academico']['ofertas'] as &$r)if($r['id']===9001)$r['estado']='Cerrada';});check(count(messages('ofertas',9001,'estado'))===$closedBefore+2,'Cierre de oferta avisa a la empresa y sus postulantes');
$all=$db->query('SELECT body FROM intranet_mail WHERE source_type IN ("empresas","ofertas","postulaciones")')->fetchAll(PDO::FETCH_COLUMN);check(!str_contains(implode('',$all),'PruebaIntranet-2026!')&&!str_contains(implode('',$all),'%PDF'),'Bolsa no envía contraseñas ni currículos adjuntos');
$exp=$data['expedientes'][0];$expBefore=count(messages('expedientes',$exp['id'],'seguimiento'));edit(function(&$d)use($exp){foreach($d['expedientes'] as &$r)if($r['id']===$exp['id']){$r['area']='DG';$r['estado']='Derivado';}});check(count(messages('expedientes',$exp['id'],'seguimiento'))===$expBefore+2,'Mesa de Partes también notifica derivación');
$legacy=['source_type'=>'expedientes','source_id'=>'','record_id'=>$exp['id']];check(PortalNotifications::exists($app->bootstrap()['data'],$legacy),'Cola anterior a la actualización mantiene compatibilidad');
$before=total();$db->beginTransaction();PortalNotifications::received($db,'empresas',['id'=>999999,'nom'=>'Empresa revertida','correo'=>'revertida@example.test'],$data);$db->rollBack();check(total()===$before,'Notificaciones se revierten con la transacción');
$db->beginTransaction();PortalMail::queue($db,'empresas',(string)$cid,'prueba','largo','destino@example.test','QA-LARGO',str_repeat('A',400),str_repeat('ñ',40000));$long=$db->query("SELECT subject,body FROM intranet_mail WHERE reference='QA-LARGO'")->fetch();check(strlen($long['subject'])<=255&&strlen($long['body'])<65535&&str_contains($long['body'],'Mensaje resumido'),'Mensaje extenso se resume sin impedir guardar la gestión');$db->rollBack();
$before=total();$app->logout();$app->login(['username'=>'estudiante','password'=>'PruebaIntranet-2026!']);try{edit(function(&$d){$d['academico']['postulaciones'][0]['estado']='Seleccionado';});throw new RuntimeException('Permiso omitido');}catch(PortalError $e){check($e->status===403&&total()===$before,'Estudiante no puede fabricar selección ni correos');}
$app->logout();echo "$count comprobaciones de notificaciones por módulo aprobadas.\n";ob_end_flush();
